={{ (() => {
  const routine = e => e.impact === 'low' && e.workaround_status === 'adequate' && !!String(e.workaround_evidence ?? '').trim() && Array.isArray(e.missing_information) && e.missing_information.length === 0 && !String(e.current_harm_evidence ?? '').trim() && !String(e.deadline_business_reason ?? '').trim();
  const e = $json.output ?? {};
  const u = $json.urgency_assessment ?? {};
  const d = $json.deadline_calculation ?? {};
  const levels = ['high', 'medium', 'low'];
  const review = reason => ({
    status: 'needs_review',
    priority: null,
    priority_label: null,
    impact: levels.includes(e.impact) ? e.impact : 'unknown',
    urgency: levels.includes(u.urgency) ? u.urgency : 'unknown',
    policy_version: 'mvp-2',
    reason
  });
  if (!levels.includes(e.impact))
    return review('Business impact is missing, unknown, or invalid.');
  if (!Array.isArray(e.missing_information) || e.missing_information.length)
    return review('Essential business evidence is missing or contradictory.');
  const routineException = routine(e) && u.urgency === 'low';
  if (!routineException &&
      (d.status !== 'calculated' || !Number.isFinite(d.hours_remaining)))
    return review('A valid deadline calculation is required for this request.');
  if (u.status !== 'calculated' || !levels.includes(u.urgency))
    return review(u.reason || 'Urgency requires review.');
  const matrix = {
    high: { high: 'P1', medium: 'P2', low: 'P3' },
    medium: { high: 'P2', medium: 'P3', low: 'P4' },
    low: { high: 'P3', medium: 'P4', low: 'P4' }
  };
  const labels = { P1: 'Critical', P2: 'High', P3: 'Medium', P4: 'Low' };
  const priority = matrix[e.impact][u.urgency];
  return {
    status: 'calculated',
    priority,
    priority_label: labels[priority],
    impact: e.impact,
    urgency: u.urgency,
    policy_version: 'mvp-2',
    reason: 'Impact ' + e.impact + ' and urgency ' + u.urgency +
      ' map to ' + priority + ' under the MVP priority matrix.' +
      (routineException ? ' Urgency uses the routine workaround exception; the requested deadline remains unparsed.' : '')
  };
})() }}

