assignments.value:
={{ (() => {
  const matches = $json.knowledge_matches;

  if (!Array.isArray(matches)) {
    throw new Error(
      'Expected knowledge_matches array from Aggregate Knowledge.'
    );
  }

  const context = $('Prepare Priority Context').first().json;
  const priority = $('Map Jira Priority').first().json;
  const seen = new Set();
  const articles = [];

  for (const match of matches) {
    const document = match.document;
    const metadata = document?.metadata;

    if (
      !document?.pageContent ||
      !metadata?.page_id ||
      metadata.knowledge_approval !== 'approved' ||
      String(metadata.space_id) !== 'YOUR_CONFLUENCE_SPACE_ID'
    ) {
      continue;
    }

    const key = JSON.stringify([
      metadata.page_id,
      metadata.source_version,
      document.pageContent.trim()
    ]);

    if (seen.has(key)) continue;
    seen.add(key);

    articles.push({
      article_id: metadata.article_id,
      page_id: metadata.page_id,
      title: metadata.title,
      source_url: metadata.source_url,
      source_version: metadata.source_version,
      category: metadata.category,
      knowledge_approval: metadata.knowledge_approval,
      automatic_response_allowed:
        metadata.automatic_response_allowed === true,
      text: document.pageContent.trim()
    });
  }

  return {
    request: JSON.parse(context.assessment_context),
    triage: context.output,
    priority: priority.priority_assessment,
    jira_priority: priority.jira_priority,
    knowledge_status:
      articles.length > 0
        ? 'candidates_found'
        : 'no_approved_knowledge',
    unique_passage_count: articles.length,
    knowledge_allows_automatic_response:
      articles.length > 0 &&
      articles.every(
        article => article.automatic_response_allowed === true
      ),
    knowledge_passages: articles
  };
})() }}

