conditions.leftValue:
={{ (() => {
  const context =
    $('Prepare Resolution Context').first().json.resolution_context;

  const draft = $json.output;
  if (!context || !draft) return false;

  const triage = context.triage ?? {};
  const priority = context.priority ?? {};
  const passages = context.knowledge_passages;
  const citations = draft.citations;

  const emptyArray = value =>
    Array.isArray(value) && value.length === 0;

  const hasText = value =>
    typeof value === 'string' && value.trim().length > 0;

  if (
    priority.status !== 'calculated' ||
    priority.priority !== 'P4' ||
    priority.impact !== 'low' ||
    priority.urgency !== 'low'
  ) return false;

  if (
    triage.security_status !== 'none_reported' ||
    !emptyArray(triage.security_indicators) ||
    !emptyArray(triage.missing_information) ||
    !emptyArray(triage.clarification_questions)
  ) return false;

  if (
    context.knowledge_status !== 'candidates_found' ||
    context.knowledge_allows_automatic_response !== true ||
    !Array.isArray(passages) ||
    passages.length === 0
  ) return false;

  const approvedPassages = passages.every(p =>
    p.knowledge_approval === 'approved' &&
    p.automatic_response_allowed === true &&
    p.category === triage.category &&
    hasText(p.article_id) &&
    hasText(p.source_url) &&
    Number.isInteger(p.source_version) &&
    p.source_version > 0 &&
    hasText(p.text)
  );

  if (!approvedPassages) return false;

  if (
    draft.knowledge_applicability !== 'supported' ||
    !hasText(draft.draft_response) ||
    !Array.isArray(citations) ||
    citations.length === 0
  ) return false;

  return citations.every(c =>
    passages.some(p =>
      c.article_id === p.article_id &&
      c.source_url === p.source_url &&
      c.source_version === p.source_version
    )
  );
})() }}

parameters.completionMessage:
={{ (() => {
  const draft = $('Automatic Response Eligible').first().json.output;

  const escapeHtml = value => String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');

  const message = [
    'Request registered: ' + $json.key,
    'Automated guidance based on approved IT knowledge:',
    draft.draft_response,
    'Knowledge references:\n' + draft.citations.map(ref =>
      ref.article_id + ' — Version ' + ref.source_version +
      '\n' + ref.source_url
    ).join('\n\n'),
    'Check whether the page is now usable. If the issue continues, contact IT and quote ' + $json.key + '.',
    'Your ticket remains open; resolution has not been confirmed.'
  ].join('\n\n');

  return escapeHtml(message).replace(/\n/g, '<br>');
})() }}

